//! 🧪️ Actual standard Arc root nulls, retries and native close consume one original finite bank.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn debit(bank:&mut RetainedCloneGrant,work:u64,p:RetainedCloneProgress){assert!(work<=bank.maximum_items as u64);assert!(p.fits(*bank));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]
fn cancel_root_actual_null_and_native_close_keep_one_original_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();assert_eq!(schema["properties"]["laws"]["const"],law["laws"]);let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let d=CancelToken::root_admission_demands();let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()};
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,h)=observe(||CancelToken::admit_root(denied));assert_eq!(turn.work,law["work"]["denied"].as_u64().unwrap());assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));}
 let((turn,attempts),h)=observe(||refuse(||CancelToken::admit_root(g)));assert_eq!(attempts,1);assert_eq!(turn.work,law["work"]["null"].as_u64().unwrap());assert_eq!(turn.result.unwrap_err().kind,semio_framework_value::ValueRefusalKind::AllocationFailed);assert_eq!(h,(0,0));debit(&mut bank,turn.work,Default::default());
 let(turn,h)=observe(||CancelToken::admit_root(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;assert_eq!(work,law["work"]["born"].as_u64().unwrap());let(root,p)=turn.result.unwrap().unwrap();assert_eq!(h,(p.retained_capacity_bytes,0));assert_eq!(p.retained_capacity_bytes,d.capacity_bytes);assert_eq!(Arc::strong_count(&root.0),1);debit(&mut bank,work,p);let born=h.0;let(oracle,_registration)=futures_util::future::AbortHandle::new_pair();assert_eq!(root.is_cancelled_now(),oracle.is_aborted());let mut owner=crate::CancelTokenRetirement::from_token(root);let mut freed=0;
 for _ in 0..stock["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let(turn,h)=observe(||owner.close_step(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.retained_capacity_bytes,0);debit(&mut bank,work,p);freed+=h.1;}assert!(owner.terminal_is_empty());let(turn,h)=observe(||owner.close_step(Default::default()));assert_eq!(turn.work,law["work"]["cached"].as_u64().unwrap());assert!(matches!(turn.result,Ok(RetainedCloneStep::Complete(p))if p==Default::default()));assert_eq!(h,(0,0));assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(born,freed);
}
